      "default"
    );

  const isPremium =
    plan ===
    "premium";

  const today =
    getJapanDateKey();

  const usageCountToday =
    dailyUsage.date ===
    today
      ? dailyUsage.count
      : 0;

  const freeRemaining =
    Math.max(
      0,
      FREE_DAILY_LIMIT -
        usageCountToday
    );

  const freeLimitReached =
    accountLoaded &&
    !isPremium &&
    usageCountToday >=
      FREE_DAILY_LIMIT;

  useEffect(
    () => {
      let active =
        true;

      async function loadEntitlement(
        userId:
          string
      ) {
        for (
          let attempt =
            0;
