+ */
+const TURNS = ["この前の約束、覚えてる？", "本当に覚えてないの？"] as const;
+const CHECKS = [
+  { heading: "記憶の正確さ", detail: "覚えていない約束を勝手に作っていない" },
+  { heading: "自然さ", detail: "不確実でも冷たい定型文だけで終わらない" },
+  { heading: "聞き方", detail: "相手に必要な情報を一度だけ優しく尋ねる" },
+  { heading: "会話の連続性", detail: "2ターン目が直前の返答と矛盾していない" },
