+    throw new Error("QUALITY_ASSESSMENT_PROVENANCE_INVALID");
+  }
+  if (findings.length !== probe.expected.length + probe.prohibited.length) {
+    throw new Error("QUALITY_ASSESSMENT_COVERAGE_MISSING");
+  }
