test("rejects missing replies, malformed metadata, and invalid timezone", () => {
  assert.throws(() => importRecordedQualityReplies({ probe, replies: ["one"], manifest }), /TRANSCRIPT_INVALID/);
  assert.throws(() => importRecordedQualityReplies({
