+  for (const payload of [
+    { candidates: [{ content: { parts: [] } }] },
+    { candidates: [{ content: { parts: [{ text: "invalid json" }] } }] },
+    { candidates: [{ content: { parts: [{ text: '{"reply":""}' }] } }] },
+  ]) {
+    let calls = 0;
+    const fetcher = (async () => {
+      calls++;
+      return { ok: true, text: async () => JSON.stringify(payload) };
+    }) as unknown as typeof fetch;
+    await assert.rejects(runLiveSmokeProbe({ [REDACTED], approved: true, fetcher, manifest }));
+    assert.equal(calls, 1);
+  }
+});
+
+test("no opt-in means no network request", async () => {
+  let called = false;
+  const fetcher = (async () => { called = true; throw new Error("should not be called"); }) as unknown as typeof fetch;
+  await assert.rejects(runLiveSmokeProbe({ [REDACTED], approved: false, fetcher, manifest }));
+  assert.equal(called, false);
+});
