+      return true;
+    });
+  assert.equal(calls, 1);
+});
+
+test("our timer-aborted model fetch is classified as timeout without retry", async () => {
+  let calls = 0;
+  const fetcher = (async (_url: string, init: RequestInit) => {
+    calls++;
+    await new Promise<void>((_resolve, reject) => {
