+  await assert.rejects(runLiveSmokeProbe({ [REDACTED], approved: true, fetcher, manifest }),
+    (error: unknown) => { assert.ok(error instanceof SmokeProbeFailure); assert.equal(error.code, "network"); return true; });
+});
+
