              -MAX_MESSAGES
            );

        localStorage
          .setItem(
            STORAGE_KEY,

            JSON.stringify(
              limitedMessages
            )
          );
      } catch (
        error
      ) {
        console.error(
          "Failed to save chat history:",
          error
        );
      }
    },
    [
      messages,
      loaded,
    ]
  );

  async function getAccessToken() {
    const {
      data,
      error,
    } =
      await supabase
        .auth
        .getSession();

    if (
      error
    ) {
      throw error;
    }

    const accessToken =
      data
        .session
        ?.access_token;

    if (
      !accessToken
    ) {
      throw new Error(
        "ログイン情報を確認できませんでした。ページを再読み込みしてね。"
      );
    }

    return accessToken;
  }

  function applyApiUsage(
    value:
      unknown
  ) {
    if (
      !value ||
      typeof value !==
        "object"
    ) {
      return;
    }

    const usage =
      value as
        ApiUsage;

    if (
      usage
