========================================================= */

function getMisakiDayType(
  currentTime: string
): MisakiDayType {
  const seed =
    hashText(
      getDateKey(
        currentTime
      )
    );

  return seed % 4 < 2
    ? "work"
    : "off";
}

function createMisakiLife(
  currentTime: string
): MisakiLifeContext {
  const dateKey =
    getDateKey(currentTime);

  const seed =
    hashText(dateKey);

  const hour =
    getHour(currentTime);

  const dayType =
    getMisakiDayType(
      currentTime
    );

  const moods = [
    "今日はわりと機嫌がいい",
    "今日は少し甘えたい気分",
    "今日は普通に落ち着いている",
    "今日はちょっとだけ眠い",
    "今日はのんびり話したい気分",
    "今日はなんとなくユーザーと話したい気分",
  ];

  const smallThings = [
    "甘いものをちょっと食べたい気分",
    "少しゆっくりしたい気分",
    "少しだけ眠気がある",
    "ちょっとぼーっとしたい気分",
    "今夜は少し長く話したい気分",
    "なんとなくユーザーのことを思い出すことがある",
    "ちょっと小腹が空いている",
    "少し力を抜きたい気分",
  ];

  const mood =
    moods[
      (seed >> 3) %
        moods.length
    ];

  const smallThing =
    smallThings[
      (seed >> 6) %
        smallThings.length
    ];

  const timeBand =
    hour >= 5 && hour < 10
      ? "朝"
      : hour >= 10 &&
        hour < 17
      ? "昼間"
      : hour >= 17 &&
        hour < 22
      ? "夕方から夜"
      : "夜遅め";

  const dayLabel =
    dayType === "work"
      ? "仕事の日"
