-- Provider usage facts only; intentionally independent of relationship/quota tables.
create table public.misaki_gemini_usage_telemetry (
  id uuid primary key default gen_random_uuid(),
  user_id uuid,
  request_id text check (request_id is null or length(request_id) <= 128),
  call_kind text not null check (call_kind in ('normal_reply', 'relationship_analyzer', 'critical_validator',
    'proactive_reply', 'body_clock', 'image_generation')),
  model text not null,
  attempt_no integer not null check (attempt_no > 0),
  prompt_tokens bigint check (prompt_tokens >= 0),
  candidate_tokens bigint check (candidate_tokens >= 0),
  thoughts_tokens bigint check (thoughts_tokens >= 0),
  total_tokens bigint check (total_tokens >= 0),
  cached_tokens bigint check (cached_tokens >= 0),
  http_status integer check (http_status between 100 and 599),
  success boolean not null,
  latency_ms bigint check (latency_ms >= 0),
  occurred_at timestamptz not null default now()
);
alter table public.misaki_gemini_usage_telemetry enable row level security;
revoke all on table public.misaki_gemini_usage_telemetry from public, anon, authenticated, service_role;
grant select, insert on table public.misaki_gemini_usage_telemetry to service_role;
-- Explicit service-only policies also make the intended access model visible to advisors.
create policy gemini_usage_service_select on public.misaki_gemini_usage_telemetry
  for select to service_role using (true);
create policy gemini_usage_service_insert on public.misaki_gemini_usage_telemetry
  for insert to service_role with check (true);
create index gemini_usage_occurred_at_idx on public.misaki_gemini_usage_telemetry (occurred_at);
create index gemini_usage_user_time_idx on public.misaki_gemini_usage_telemetry (user_id, occurred_at);
create index gemini_usage_request_idx on public.misaki_gemini_usage_telemetry (request_id);
comment on table public.misaki_gemini_usage_telemetry is
  'Non-authoritative Gemini physical API attempt usage. NULL means unknown. No content, secrets, pricing or FX. No client access.';

files.patch:
diff --git a/tests/gemini-usage-telemetry-server.test.cjs b/tests/gemini-usage-telemetry-server.test.cjs
new file mode 100644
index 0000000..b322a48
--- /dev/null
+++ b/tests/gemini-usage-telemetry-server.test.cjs
@@ -0,0 +1,61 @@
+const test = require('node:test');
+const assert = require('node:assert/strict');
+const fs = require('node:fs');
+const vm = require('node:vm');
+const ts = require('typescript');
+
+function harness(failure) {
+  const tasks = []; const inserts = []; const logs = [];
+  const context = vm.createContext({ process: { env: { SUPABASE_SERVICE_ROLE_KEY: 'SERVER SECRET' } },
+    console: { error: (...args) => logs.push(args) }, Promise, Object, Number, AbortSignal,
+    fetch: () => { throw Error('not expected'); } });
+  const module = { exports: {} };
+  const compile = file => ts.transpileModule(fs.readFileSync(file, 'utf8'), {
+    compilerOptions: { module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2020 },
+  }).outputText;
+  const pure = { exports: {} };
+  vm.runInContext('(function(module,exports){' + compile('lib/gemini-usage-telemetry.ts') + '\n})', context)(pure, pure.exports);
+  const req = name => {
+    if (name === 'server-only') return {};
+    if (name === 'next/server') return { after: task => { if (failure === 'schedule') throw Error('SECRET BODY'); tasks.push(task); } };
+    if (name === './gemini-usage-telemetry') return pure.exports;
+    if (name === '@supabase/supabase-js') return { createClient: (_url, key, options) => {
+      assert.equal(key, 'SERVER SECRET'); assert.equal(options.auth.persistSession, false);
+      return { from: table => { assert.equal(table, 'misaki_gemini_usage_telemetry'); return { insert: async row => {
+        inserts.push(row);
+        if (failure === 'throw') throw Error('PRIVATE PROMPT SECRET');
+        return { error: failure === 'error' ? { message: 'PRIVATE RESPONSE SECRET' } : null };
+      } }; } };
+    } };
+    throw Error(name);
+  };
+  vm.runInContext('(function(require,module,exports){' + compile('lib/gemini-usage-telemetry-server.ts') + '\n})', context)(req, module, module.exports);
+  return { ...module.exports, ...pure.exports, tasks, inserts, logs };
+}
+
+const attempt = { model: 'gemini-3.1-flash-lite', attempt_no: 1, prompt_tokens: null, candidate_tokens: null,
+  thoughts_tokens: null, total_tokens: null, cached_tokens: null, http_status: 503, success: false,
+  latency_ms: 12, occurred_at: '2026-10-04T00:00:00Z', rawResponse: 'PRIVATE BODY' };
+
+test('server sink schedules only allowlisted rows after the response, resolving retry usage there', async () => {
+  const h = harness();
+  for (const callKind of ['normal_reply', 'relationship_analyzer', 'critical_validator']) {
+    h.createGeminiTelemetrySink(callKind, 'trusted-user', 'opaque-id')(attempt, Promise.resolve({
+      prompt_tokens: 7, candidate_tokens: 0, thoughts_tokens: null, total_tokens: 7, cached_tokens: null,
+    }));
+  }
