import { CRITICAL_TYPES, EVIDENCE_TYPES, parseEvidence, type CriticalType, type Turn } from "./relationship-engine-v1.ts";

const EVIDENCE_RESPONSE_SCHEMA = {
  type: "OBJECT",
  properties: {
    evidence: {
      type: "ARRAY",
      maxItems: 5,
