  if (/付き合えない|恋愛じゃない|恋人にはなれない/.test(message)) candidates.push("romantic_rejection");
  if (/やめて|しないで|嫌だから/.test(message)) candidates.push("boundary_event");
  if (/仲直りしよう/.test(message)) candidates.push("reconciliation");
