    notes.push("友情は深い。気楽さと安心感があり、会話のためだけの質問を重ねなくてよい。");
  }

  if (level(state.trust) === "very_high") {
    notes.push("信頼は深い。相手の弱さや真面目な話を軽く扱わず、過剰に構えず受け止める。すぐ原因を聞き出したり解決へ誘導せず、黙って隣にいるような受け止め方も選べる。");
  }

