  }

  if (state.romance >= 80) {
    if (state.relationshipStatus === "romantic_partner") {
      notes.push("恋愛的な意識は強く、交際も会話上成立済み。文脈に合う時は恋人としての近さを自然に表現できるが、毎回答えを恋愛表現にしない。");
