source.text:
:root {
  --misaki-main: #ff6680;
  --misaki-main-dark: #e95872;
  --misaki-sub: #ffd5de;
  --misaki-beige: #f8efea;
  --misaki-paper: #fffafa;
  --misaki-white: #ffffff;
  --misaki-text: #6c5c62;
  --misaki-title: #49383e;
  --misaki-muted: #9a8b90;
  --misaki-line: rgba(108, 92, 98, 0.11);
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
  min-height: 100%;
}

html {
  background: var(--misaki-beige);
}

body {
  background:
    radial-gradient(
      circle at 50% 0%,
      rgba(255, 213, 222, 0.35),
      transparent 380px
    ),
    var(--misaki-beige);

  color: var(--misaki-text);

  font-family:
    -apple-system,
    BlinkMacSystemFont,
    "Hiragino Sans",
    "Yu Gothic",
    "Meiryo",
    sans-serif;

  -webkit-font-smoothing: antialiased;
}

button,
input,
textarea {
  font: inherit;
}

button {
  -webkit-tap-highlight-color: transparent;
}

/* ========================================
   CHAT APP
======================================== */

.shell {
  width: 100%;
  max-width: 480px;
  min-height: 100dvh;

  margin: 0 auto;

  display: flex;
  flex-direction: column;

  position: relative;

  background:
    linear-gradient(
      180deg,
      #fffafa 0%,
      #fdf5f5 34%,
      #f8efea 100%
    );

  color: var(--misaki-text);

  overflow-x: hidden;
}

/* ========================================
   HEADER
======================================== */

.shell .card {
  position: sticky;
  top: 0;
  z-index: 20;

  min-height: 79px;

  display: flex;
  align-items: center;
  gap: 11px;

  padding:
    calc(11px + env(safe-area-inset-top))
    14px
    11px;

  background:
    rgba(255, 250, 250, 0.94);

  border-bottom:
    1px solid
    rgba(108, 92, 98, 0.08);

  box-shadow:
    0 5px 24px
    rgba(82, 55, 64, 0.055);

  backdrop-filter:
    blur(18px);

  -webkit-backdrop-filter:
    blur(18px);
}

.shell .avatar {
  flex: 0 0 auto;

  width: 49px;
  height: 49px;

  padding: 2px;

  border-radius: 50%;

  background:
    linear-gradient(
      145deg,
      #ffd5de,
      #ff6680
    );

  box-shadow:
    0 5px 16px
    rgba(189, 84, 107, 0.18);
}

.shell .avatar img {
  width: 100%;
  height: 100%;

  display: block;

  object-fit: cover;

  border:
    2px solid
    rgba(255, 255, 255, 0.94);

  border-radius: 50%;
}

.shell .card h1 {
  margin: 0;

  color:
    var(--misaki-title);

  font-size: 18px;
  line-height: 1.15;

  font-weight: 800;

  letter-spacing:
    0.04em;
}

.shell .card p {
  margin:
    4px 0 0;

  color:
    var(--misaki-muted);

  font-size: 10px;
  line-height: 1.3;
}

/*
  page.tsx 側のヘッダーボタンは
  inline style を使っているので、
  ブランド色へ統一する。
*/

.shell .card button {
  color:
    var(--misaki-text) !important;

  font-weight: 600;
}

.shell .card button:first-of-type {
  background:
    var(--misaki-main) !important;

  color:
    #ffffff !important;

  box-shadow:
    0 5px 14px
    rgba(255, 102, 128, 0.18);
}

/* ========================================
   SAFETY NOTICE
======================================== */

.shell .notice {
  margin:
    11px 13px 0;

  padding:
    9px 13px;

  border:
    1px solid
    rgba(255, 102, 128, 0.08);

  border-radius:
    13px;

  background:
    rgba(255, 255, 255, 0.68);

  color:
    #918086;

  font-size:
    10px;

  line-height:
    1.55;

  text-align:
    center;

  box-shadow:
    0 5px 18px
    rgba(74, 52, 59, 0.025);
}

/* ========================================
   CHAT AREA
======================================== */

.shell .chat {
  flex: 1;

  width: 100%;

  padding:
    20px
    13px
    126px;

  display: flex;
  flex-direction: column;

  gap: 13px;
}

/* ========================================
   CHAT BUBBLES
======================================== */

.shell .chat .bubble {
  position: relative;

  width:
    fit-content;

  max-width:
    78%;

  padding:
    10px 14px;

  color:
    var(--misaki-text);

  font-size:
    15px;

  line-height:
    1.58;

  letter-spacing:
    0.005em;

  white-space:
    pre-wrap;

  overflow-wrap:
    anywhere;

  box-shadow:
    0 4px 14px
    rgba(73, 50, 58, 0.045);
}

/* 美咲 */

.shell
  .chat
  .bubble:not(.user) {
  align-self:
    flex-start;

  margin-left:
    45px;

  background:
    rgba(255, 255, 255, 0.96);

  border:
    1px solid
    rgba(108, 92, 98, 0.045);

  border-radius:
    18px
    18px
    18px
    5px;
}

.shell
  .chat
  .bubble:not(.user)::before {
  content: "";

  position:
    absolute;

  left:
    -45px;

  top:
    0;

  width:
    35px;

  height:
    35px;

  border:
    2px solid
    #ffffff;

  border-radius:
    50%;

  background-image:
    url("/icon-192.png");

  background-size:
    cover;

  background-position:
    center;

  background-repeat:
    no-repeat;

  box-shadow:
    0 4px 12px
    rgba(90, 58, 69, 0.11);
}

/* ユーザー */

.shell
  .chat
  .bubble.user {
  align-self:
    flex-end;

  margin-left:
    auto;

  background:
    linear-gradient(
      145deg,
      #ffdce3,
      var(--misaki-sub)
    );

  color:
    #5f4c53;

  border:
    1px solid
    rgba(216, 104, 128, 0.06);

  border-radius:
    18px
    18px
    5px
    18px;

  box-shadow:
    0 4px 13px
    rgba(199, 98, 120, 0.055);
}

/* ========================================
   TYPING
======================================== */

.shell .typingBubble {
  min-width:
    61px;

  height:
    40px;

  display:
    flex;

  align-items:
    center;

  justify-content:
    center;

  gap:
    5px;

  padding:
    0 13px;
}

.shell .typingBubble span {
  width:
    6px;

  height:
    6px;

  display:
    block;

  border-radius:
    50%;

  background:
    #c08f99;

  animation:
    typingDot
    1.2s
    infinite
    ease-in-out;
}

.shell .typingBubble .waitingReplyText {
  width: auto;
  height: auto;
  display: inline;
  border-radius: 0;
  background: transparent;
  animation: none;
  white-space: nowrap;
  font-size: 13px;
  line-height: 1.4;
  color: #8f737b;
