    0s;
}

.shell
  .typingBubble
  span:nth-child(2) {
  animation-delay:
    0.18s;
}

.shell
  .typingBubble
  span:nth-child(3) {
  animation-delay:
    0.36s;
}

@keyframes typingDot {
  0%,
  60%,
  100% {
    opacity:
      0.3;

    transform:
      translateY(0);
  }

  30% {
    opacity:
      1;

    transform:
