/* ========================================
   INPUT AREA
======================================== */

.shell .inputArea {
  position:
    fixed;

  z-index:
    30;

  left:
    50%;

  bottom:
    0;

  transform:
    translateX(-50%);

  width:
    min(
      100%,
      480px
    );

  display:
    flex;

  align-items:
    center;

  gap:
    8px;

  padding:
    9px
    10px
    calc(
      9px +
      env(
        safe-area-inset-bottom
      )
    );

  background:
    rgba(
      255,
      250,
      250,
      0.96
    );

  border-top:
    1px solid
    rgba(
      108,
      92,
      98,
      0.08
    );

  box-shadow:
    0 -7px 25px
    rgba(
      73,
      48,
      57,
      0.055
    );

