async function getEarthquakeEvents():
  Promise<
    TokyoLifeEvent[]
  > {
  const feed =
    await fetchText(
      JMA_EARTHQUAKE_FEED,
      300
    );

  if (!feed) {
    return [];
  }

  const entries =
    getEntries(
      feed
    );

  const candidates =
    entries.filter(
      (entry) => {
        const title =
          getTag(
            entry,
            "title"
          );

        return (
          title.includes(
            "震度速報"
          ) ||
          title.includes(
            "震源・震度"
          ) ||
          title.includes(
            "地震情報"
          )
        );
      }
    );

  const results:
    TokyoLifeEvent[] = [];

  for (
    const entry
    of candidates
  ) {
    if (
      results.length >=
      2
    ) {
      break;
    }

    const updated =
      getTag(
        entry,
        "updated"
      );

    if (
      !isRecent(
        updated,
        3
      )
    ) {
      continue;
    }

    const detailUrl =
      getLink(
        entry
      );

    if (
      !detailUrl
    ) {
      continue;
    }

    const detailXml =
      await fetchText(
        detailUrl,
        300
      );

    if (
      !detailXml
    ) {
      continue;
    }

    const headline =
      getTag(
        detailXml,
        "Headline"
      );

    const infoType =
      getTag(
        detailXml,
        "Title"
      );

    const combined =
      `${infoType} ${headline} ${stripTags(
        detailXml
      )}`;

    if (
      !affectsTokyo(
        combined
      )
    ) {
      continue;
    }

    const meaningful =
      /震度[３3４4５5６6７7]/.test(
        combined
      );

    if (
      !meaningful
    ) {
      continue;
    }

    results.push({
      type:
        "earthquake",

      title:
        "東京で体感する可能性のある地震",

      detail:
        headline ||
        infoType ||
        "東京周辺で地震情報が発表されています。",

      publishedAt:
        updated,

      source:
        "気象庁",
    });
  }

  return results;
}

/*
 * ===========================
 * 気象警報
 * ===========================
 */

function isRelevantWarningTitle(
  title: string
) {
  return (
    title.includes(
      "気象警報"
    ) ||
    title.includes(
      "気象特別警報"
    ) ||
    title.includes(
      "土砂災害警戒情報"
    ) ||
    title.includes(
      "竜巻注意情報"
    )
  );
}

function isCancelledWarning(
  text: string
) {
  const normalized =
    normalizeText(
      text
    );

  return (
    normalized.includes(
      "すべて解除"
    ) ||
    normalized.includes(
      "全て解除"
    ) ||
    normalized.includes(
      "警報を解除"
    ) ||
    normalized.includes(
      "注意報を解除"
    ) ||
    normalized.includes(
      "解除しました"
    )
  );
}

function createWarningDetail(
  title: string,
  headline: string
) {
  if (
    title.includes(
      "土砂災害警戒情報"
    )
  ) {
    return (
      headline ||
      "東京都内に土砂災害警戒情報が発表されています。"
    );
  }

  if (
    title.includes(
      "竜巻注意情報"
    )
  ) {
    return (
      headline ||
      "東京都内に竜巻注意情報が発表されています。"
    );
  }

  if (
    title.includes(
      "気象特別警報"
    )
  ) {
    return (
      headline ||
      "東京都内に気象特別警報が発表されています。"
    );
  }

  return (
    headline ||
    "東京都内に気象警報・注意報の情報が発表されています。"
  );
}

async function getWeatherWarningEvents():
  Promise<
    TokyoLifeEvent[]
  > {
  const feed =
    await fetchText(
      JMA_EXTRA_FEED,
      300
    );

  if (!feed) {
    return [];
  }

  const entries =
    getEntries(
      feed
    );

  const candidates =
    entries.filter(
      (entry) => {
        const title =
          getTag(
            entry,
            "title"
          );

        return (
          isRelevantWarningTitle(
            title
          )
        );
      }
    );

  const results:
    TokyoLifeEvent[] = [];

  const seen =
    new Set<string>();

  for (
    const entry
    of candidates
  ) {
    if (
      results.length >=
      3
    ) {
      break;
    }

    const updated =
      getTag(
        entry,
        "updated"
      );

    if (
      !isRecent(
        updated,
        3
      )
    ) {
      continue;
    }

    const detailUrl =
      getLink(
        entry
      );

    if (
      !detailUrl
    ) {
      continue;
    }

    const detailXml =
      await fetchText(
        detailUrl,
        300
      );

    if (
      !detailXml
    ) {
      continue;
    }

    const plainText =
      stripTags(
        detailXml
      );

    if (
      !affectsKoto(
        plainText
      )
    ) {
      continue;
    }

    const headline =
      getTag(
        detailXml,
        "Headline"
      );

    const title =
      getTag(
        entry,
        "title"
      );

    const combined =
      `${title} ${headline} ${plainText}`;

    if (
      isCancelledWarning(
        combined
      )
    ) {
      continue;
    }

    if (
      seen.has(
        title
      )
    ) {
      continue;
    }

    seen.add(
      title
    );

    results.push({
      type:
        "weather_warning",

      title,

      detail:
        createWarningDetail(
          title,
          headline
        ),

      publishedAt:
        updated,

      source:
        "気象庁",
    });
  }

  return results;
}

/*
 * ===========================
 * 江東区周辺
 * 今後6時間の天気
 * ===========================
 */

type OpenMeteoHourly = {
  time?: string[];

  precipitation_probability?:
    number[];

  precipitation?:
    number[];

  rain?:
    number[];

  weather_code?:
    number[];
};

type OpenMeteoResponse = {
  hourly?:
    OpenMeteoHourly;
};

type HourlyWeather = {
  time: string;

  probability:
    number;

  precipitation:
    number;

  rain:
    number;

  weatherCode:
    number;
};

function weatherCodeToText(
  code: number
) {
  if (
    code === 0
  ) {
    return "晴れ";
  }

  if (
    code === 1 ||
    code === 2
  ) {
    return (
      "晴れ時々くもり"
    );
  }

  if (
    code === 3
  ) {
    return "くもり";
  }

  if (
    code === 45 ||
    code === 48
  ) {
    return "霧";
  }

  if (
    code >= 51 &&
    code <= 57
  ) {
    return "霧雨";
  }

  if (
    code >= 61 &&
    code <= 67
  ) {
    return "雨";
  }

  if (
    code >= 71 &&
    code <= 77
  ) {
    return "雪";
  }

  if (
    code >= 80 &&
    code <= 82
  ) {
    return "にわか雨";
  }

  if (
    code >= 85 &&
    code <= 86
  ) {
    return "にわか雪";
  }

  if (
    code >= 95
  ) {
    return "雷雨";
  }

  return "不明";
}

function formatHour(
  value: string
) {
  const match =
    value.match(
      /T(\d{2}):(\d{2})/
    );

  if (
    !match
  ) {
    return value;
  }

  return `${Number(
    match[1]
  )}時`;
}

function buildHourlyWeather(
  hourly:
    OpenMeteoHourly
) {
  const times =
    hourly.time ??
    [];

  const probabilities =
    hourly
      .precipitation_probability ??
    [];

  const precipitation =
    hourly.precipitation ??
    [];

  const rain =
    hourly.rain ??
    [];

  const codes =
    hourly.weather_code ??
    [];

  const result:
    HourlyWeather[] =
    [];

  for (
    let i = 0;
    i < times.length;
    i += 1
  ) {
    const time =
      times[i];

    if (
      !time
    ) {
      continue;
    }

    result.push({
      time,

      probability:
        typeof probabilities[
          i
        ] === "number"
          ? probabilities[i]
          : 0,

      precipitation:
        typeof precipitation[
          i
        ] === "number"
          ? precipitation[i]
          : 0,

      rain:
        typeof rain[
          i
        ] === "number"
          ? rain[i]
          : 0,

      weatherCode:
        typeof codes[
          i
        ] === "number"
          ? codes[i]
          : 0,
    });
  }

  return result;
}

function hasMeaningfulWeather(
  points:
    HourlyWeather[]
) {
  return points.some(
    (point) =>
      point.probability >=
        40 ||
      point.precipitation >=
        0.2 ||
      point.rain >=
        0.2 ||
      point.weatherCode >=
        95
  );
}

function createForecastDetail(
  points:
    HourlyWeather[]
) {
  const rainy =
    points.filter(
      (point) =>
        point.probability >=
          40 ||
        point.precipitation >=
          0.2 ||
        point.rain >=
          0.2
    );

  const thunder =
    points.filter(
      (point) =>
        point.weatherCode >=
        95
    );

  const maxProbability =
    points.reduce(
      (
        current,
        point
      ) =>
        Math.max(
          current,
          point.probability
        ),
      0
    );

  const maxRain =
    points.reduce(
      (
        current,
        point
      ) =>
        Math.max(
          current,
          point.rain,
          point.precipitation
        ),
      0
    );

  const parts:
    string[] = [];

  if (
    rainy.length > 0
  ) {
    const first =
      rainy[0];

    const last =
      rainy[
        rainy.length -
          1
      ];

    if (
      first &&
      last
    ) {
      if (
        first.time ===
        last.time
      ) {
        parts.push(
          `${formatHour(
            first.time
          )}ごろに雨の可能性があります。`
        );
      } else {
        parts.push(
          `${formatHour(
            first.time
          )}ごろから${formatHour(
            last.time
          )}ごろにかけて雨の可能性があります。`
        );
      }
    }
  }

  if (
    maxProbability >=
    40
  ) {
    parts.push(
      `今後6時間の最大降水確率は約${Math.round(
        maxProbability
      )}%です。`
    );
  }

  if (
    maxRain >= 0.2
  ) {
    parts.push(
      `時間帯によっては1時間あたり約${maxRain.toFixed(
        1
      )}mm程度の降水が見込まれます。`
    );
  }

  if (
    thunder.length >
    0
  ) {
    parts.push(
      `${formatHour(
        thunder[0].time
      )}ごろを中心に雷雨の可能性があります。`
    );
  }

  /*
   * WMOコードの数字が一番大きいものを
   * 「強い状態」の目安として使う。
   */
  let strongest =
    points[0];

  for (
    const point
    of points
  ) {
    if (
      !strongest ||
      point.weatherCode >
        strongest.weatherCode
    ) {
      strongest =
        point;
    }
  }

  if (
    strongest
  ) {
    parts.push(
      `主な予報状態は「${weatherCodeToText(
        strongest.weatherCode
      )}」です。`
    );
  }

  return parts.join(
    " "
  );
}

async function getKotoWeatherForecastEvents():
  Promise<
    TokyoLifeEvent[]
  > {
  const hourly =
    [
      "precipitation_probability",
      "precipitation",
      "rain",
      "weather_code",
    ].join(
      ","
    );

  const url =
    "https://api.open-meteo.com/v1/forecast" +
    `?latitude=${MISAKI_LATITUDE}` +
    `&longitude=${MISAKI_LONGITUDE}` +
    `&hourly=${hourly}` +
    "&forecast_hours=6" +
    "&timezone=Asia%2FTokyo";

  const data =
    await fetchJson<
      OpenMeteoResponse
    >(
      url,
      300
    );

  if (
    !data?.hourly
  ) {
    return [];
  }

  const points =
    buildHourlyWeather(
      data.hourly
    ).slice(
      0,
      6
    );

  if (
    points.length ===
    0
  ) {
    return [];
  }

  /*
   * 晴れ・くもりだけなら
   * わざわざイベントとして
   * Geminiへ渡さない。
   *
   * 雨や雷など、
   * 会話に意味がある時だけ渡す。
   */
  if (
    !hasMeaningfulWeather(
      points
    )
  ) {
    return [];
  }

  const detail =
    createForecastDetail(
      points
    );

  if (
    !detail
  ) {
    return [];
  }

  return [
    {
      type:
        "weather_forecast",

      title:
        "江東区周辺の今後6時間の天気変化",

      detail,

      source:
        "Open-Meteo",
    },
  ];
}

/*
 * ===========================
 * JR東日本
 * ===========================
 */

function getTrainSection(
  pageText: string,
  lineName: string
) {
  const start =
    pageText.indexOf(
      lineName
    );

  if (
    start < 0
  ) {
    return null;
  }

  let end =
    pageText.length;

  for (
    const otherLine
    of TOKYO_JR_LINES
  ) {
    if (
      otherLine ===
      lineName
    ) {
      continue;
    }

    const index =
      pageText.indexOf(
        otherLine,
        start +
          lineName.length
      );

    if (
      index > start &&
      index < end
    ) {
      end =
        index;
    }
  }

  end =
    Math.min(
      end,
      start + 500
    );

  return pageText.slice(
    start,
    end
  );
}

function findTrainProblem(
  pageText: string,
  lineName: string
) {
  const nearby =
    getTrainSection(
      pageText,
      lineName
    );

  if (
    !nearby
  ) {
    return null;
  }

  const words = [
    "運転見合わせ",
    "一部列車運休",
    "直通運転中止",
    "運転再開見込",
    "運転再開",
    "運休",
    "遅延",
  ];

  const matched =
    words.find(
      (word) =>
        nearby.includes(
          word
        )
    );

  if (
    !matched
  ) {
    return null;
  }

  if (
    nearby.includes(
      "平常運転"
    ) &&
    !nearby.includes(
      "運転見合わせ"
    ) &&
    !nearby.includes(
      "一部列車運休"
    ) &&
    !nearby.includes(
      "直通運転中止"
    ) &&
    !nearby.includes(
      "運転再開見込"
    ) &&
    !nearby.includes(
      "遅延"
    )
  ) {
    return null;
  }

  return {
    status:
      matched,
  };
}

