========================================================= */

function weatherCodeToText(
  code: number | null
) {
  if (code === null) return "不明";
  if (code === 0) return "快晴";
  if (
    code === 1 ||
    code === 2
  ) return "晴れ時々くもり";
  if (code === 3) return "くもり";
  if (
    code === 45 ||
    code === 48
  ) return "霧";
  if (
    [51, 53, 55].includes(code)
  ) return "霧雨";
  if (
    [56, 57].includes(code)
  ) return "着氷性の霧雨";
  if (
    [61, 63, 65].includes(code)
  ) return "雨";
  if (
    [66, 67].includes(code)
  ) return "着氷性の雨";
  if (
    [71, 73, 75].includes(code)
  ) return "雪";
  if (code === 77) return "雪粒";
  if (
    [80, 81, 82].includes(code)
  ) return "にわか雨";
  if (
    [85, 86].includes(code)
  ) return "にわか雪";
  if (code === 95) return "雷雨";
  if (
    [96, 99].includes(code)
  ) return "ひょうを伴う雷雨";

  return "不明";
}

function getHumidityFeel(
  weather: TokyoWeather
) {
  const humidity =
    weather.relativeHumidity;

  const temperature =
    weather.temperature;

  if (
    humidity === null ||
    temperature === null
  ) {
    return null;
  }

  if (
    temperature >= 27 &&
    humidity >= 75
  ) {
    return "かなり蒸し暑く感じやすい";
  }

  if (
    temperature >= 24 &&
    humidity >= 65
  ) {
    return "やや蒸し暑く感じやすい";
  }

  if (humidity >= 75) {
    return "湿気を感じやすい";
  }

  if (humidity <= 40) {
    return "空気はやや乾燥気味";
  }

  return "湿度は特に極端ではない";
}

async function getTokyoWeather():
  Promise<TokyoWeather | null> {
  try {
    const url =
      "https://api.open-meteo.com/v1/forecast" +
      `?latitude=${MISAKI_LATITUDE}` +
      `&longitude=${MISAKI_LONGITUDE}` +
      "&current=" +
      [
        "temperature_2m",
        "apparent_temperature",
        "relative_humidity_2m",
        "precipitation",
        "rain",
        "weather_code",
        "wind_speed_10m",
      ].join(",") +
      "&timezone=Asia%2FTokyo";

    const response =
      await fetch(
        url,
        {
          next: {
            revalidate: 600,
          },
        }
      );

    if (!response.ok) {
      return null;
    }

    const data =
      await response.json();

    const current =
      data?.current;

    if (!current) {
      return null;
    }

    const numberOrNull = (
      value: unknown
    ) =>
      typeof value === "number"
        ? value
        : null;

    const weatherCode =
      numberOrNull(
        current.weather_code
      );

    return {
      temperature:
        numberOrNull(
          current.temperature_2m
        ),
      apparentTemperature:
        numberOrNull(
          current.apparent_temperature
        ),
      relativeHumidity:
        numberOrNull(
          current.relative_humidity_2m
        ),
      precipitation:
        numberOrNull(
          current.precipitation
        ),
      rain:
        numberOrNull(
          current.rain
        ),
      weatherCode,
      windSpeed:
        numberOrNull(
          current.wind_speed_10m
        ),
      description:
        weatherCodeToText(
          weatherCode
        ),
    };
  } catch (error) {
    console.error(
      "WEATHER FETCH ERROR:",
      error
    );

    return null;
  }
}

