  }
}

function isRecent(
  dateText: string,
  maxHours: number
) {
  if (!dateText) {
    return true;
  }

  const time =
    new Date(
      dateText
    ).getTime();

  if (
    !Number.isFinite(
      time
    )
  ) {
    return true;
  }

  return (
    Date.now() -
      time <=
    maxHours *
      60 *
      60 *
      1000
  );
}

