async function getEarthquakeEvents():
  Promise<
    TokyoLifeEvent[]
  > {
  const feed =
    await fetchText(
      JMA_EARTHQUAKE_FEED,
      300
    );

  if (!feed) {
    return [];
  }

  const entries =
    getEntries(
      feed
    );

  const candidates =
    entries.filter(
      (entry) => {
        const title =
          getTag(
            entry,
            "title"
          );

        return (
          title.includes(
            "震度速報"
          ) ||
          title.includes(
            "震源・震度"
          ) ||
          title.includes(
            "地震情報"
          )
        );
      }
    );

  const results:
    TokyoLifeEvent[] = [];

  for (
    const entry
    of candidates
  ) {
    if (
      results.length >=
      2
    ) {
      break;
    }

    const updated =
      getTag(
        entry,
        "updated"
      );

    if (
      !isRecent(
        updated,
        3
      )
    ) {
      continue;
    }

    const detailUrl =
      getLink(
        entry
      );

    if (
      !detailUrl
    ) {
      continue;
    }

    const detailXml =
      await fetchText(
        detailUrl,
        300
      );

    if (
      !detailXml
    ) {
      continue;
    }

    const headline =
      getTag(
        detailXml,
        "Headline"
      );

    const infoType =
      getTag(
        detailXml,
        "Title"
      );

    const combined =
      `${infoType} ${headline} ${stripTags(
        detailXml
      )}`;

    if (
      !affectsTokyo(
        combined
      )
    ) {
      continue;
    }

    const meaningful =
      /震度[３3４4５5６6７7]/.test(
        combined
      );

    if (
      !meaningful
    ) {
      continue;
    }

    results.push({
      type:
        "earthquake",

      title:
        "東京で体感する可能性のある地震",

      detail:
        headline ||
        infoType ||
        "東京周辺で地震情報が発表されています。",

      publishedAt:
        updated,

      source:
        "気象庁",
    });
  }

  return results;
}

