    )
  ) {
    return (
      headline ||
      "東京都内に気象特別警報が発表されています。"
    );
  }

  return (
    headline ||
    "東京都内に気象警報・注意報の情報が発表されています。"
  );
}

async function getWeatherWarningEvents():
  Promise<
    TokyoLifeEvent[]
  > {
  const feed =
    await fetchText(
      JMA_EXTRA_FEED,
      300
    );

  if (!feed) {
    return [];
  }

  const entries =
    getEntries(
      feed
    );

  const candidates =
    entries.filter(
      (entry) => {
        const title =
          getTag(
            entry,
            "title"
          );

        return (
          isRelevantWarningTitle(
            title
          )
        );
      }
    );

  const results:
    TokyoLifeEvent[] = [];

  const seen =
    new Set<string>();

  for (
    const entry
    of candidates
  ) {
    if (
      results.length >=
      3
    ) {
      break;
    }

    const updated =
      getTag(
        entry,
        "updated"
      );

    if (
      !isRecent(
        updated,
        3
      )
    ) {
      continue;
    }

    const detailUrl =
      getLink(
        entry
      );

    if (
      !detailUrl
    ) {
      continue;
    }

    const detailXml =
      await fetchText(
        detailUrl,
        300
      );

    if (
      !detailXml
    ) {
      continue;
    }

    const plainText =
      stripTags(
        detailXml
      );

    if (
      !affectsKoto(
        plainText
      )
    ) {
      continue;
    }

    const headline =
      getTag(
        detailXml,
        "Headline"
      );

    const title =
      getTag(
        entry,
        "title"
      );

    const combined =
      `${title} ${headline} ${plainText}`;

    if (
      isCancelledWarning(
        combined
      )
    ) {
      continue;
    }

    if (
      seen.has(
        title
      )
    ) {
      continue;
    }

    seen.add(
      title
    );

    results.push({
      type:
        "weather_warning",

      title,

      detail:
        createWarningDetail(
          title,
          headline
        ),

      publishedAt:
        updated,

      source:
        "気象庁",
    });
  }

  return results;
}

