type OpenMeteoHourly = {
  time?: string[];

  precipitation_probability?:
    number[];

  precipitation?:
    number[];

  rain?:
    number[];

  weather_code?:
    number[];
};

type OpenMeteoResponse = {
  hourly?:
    OpenMeteoHourly;
};

type HourlyWeather = {
  time: string;

  probability:
    number;

  precipitation:
    number;

  rain:
    number;

  weatherCode:
    number;
};

function weatherCodeToText(
  code: number
) {
  if (
    code === 0
  ) {
    return "晴れ";
  }

  if (
    code === 1 ||
    code === 2
  ) {
    return (
      "晴れ時々くもり"
    );
  }

  if (
    code === 3
  ) {
    return "くもり";
  }

  if (
    code === 45 ||
    code === 48
  ) {
    return "霧";
  }

  if (
    code >= 51 &&
    code <= 57
  ) {
    return "霧雨";
  }

  if (
    code >= 61 &&
    code <= 67
  ) {
    return "雨";
  }

  if (
    code >= 71 &&
    code <= 77
  ) {
    return "雪";
  }

  if (
    code >= 80 &&
    code <= 82
  ) {
    return "にわか雨";
  }

  if (
    code >= 85 &&
    code <= 86
  ) {
    return "にわか雪";
  }

  if (
    code >= 95
  ) {
    return "雷雨";
  }

  return "不明";
}

function formatHour(
  value: string
) {
  const match =
    value.match(
      /T(\d{2}):(\d{2})/
    );

  if (
    !match
  ) {
    return value;
  }

  return `${Number(
    match[1]
  )}時`;
}

function buildHourlyWeather(
  hourly:
    OpenMeteoHourly
) {
  const times =
    hourly.time ??
    [];

  const probabilities =
    hourly
      .precipitation_probability ??
    [];

  const precipitation =
    hourly.precipitation ??
    [];

  const rain =
    hourly.rain ??
    [];

  const codes =
    hourly.weather_code ??
    [];

  const result:
    HourlyWeather[] =
    [];

  for (
    let i = 0;
    i < times.length;
    i += 1
  ) {
    const time =
      times[i];

    if (
      !time
    ) {
      continue;
    }

    result.push({
      time,

      probability:
        typeof probabilities[
          i
        ] === "number"
          ? probabilities[i]
          : 0,

      precipitation:
        typeof precipitation[
          i
        ] === "number"
          ? precipitation[i]
          : 0,

      rain:
        typeof rain[
          i
        ] === "number"
          ? rain[i]
          : 0,

      weatherCode:
        typeof codes[
          i
        ] === "number"
          ? codes[i]
          : 0,
    });
  }

  return result;
}

function hasMeaningfulWeather(
  points:
    HourlyWeather[]
) {
  return points.some(
    (point) =>
      point.probability >=
        40 ||
      point.precipitation >=
        0.2 ||
      point.rain >=
        0.2 ||
      point.weatherCode >=
        95
  );
}

function createForecastDetail(
  points:
    HourlyWeather[]
) {
  const rainy =
    points.filter(
      (point) =>
        point.probability >=
          40 ||
        point.precipitation >=
          0.2 ||
        point.rain >=
          0.2
    );

  const thunder =
    points.filter(
      (point) =>
        point.weatherCode >=
        95
    );

  const maxProbability =
    points.reduce(
      (
        current,
        point
      ) =>
        Math.max(
          current,
          point.probability
        ),
      0
    );

  const maxRain =
    points.reduce(
      (
        current,
        point
      ) =>
        Math.max(
          current,
          point.rain,
          point.precipitation
        ),
      0
    );

  const parts:
    string[] = [];

  if (
    rainy.length > 0
  ) {
    const first =
      rainy[0];

    const last =
      rainy[
        rainy.length -
          1
      ];

    if (
      first &&
      last
    ) {
      if (
        first.time ===
        last.time
      ) {
        parts.push(
          `${formatHour(
            first.time
          )}ごろに雨の可能性があります。`
        );
      } else {
        parts.push(
          `${formatHour(
            first.time
          )}ごろから${formatHour(
            last.time
          )}ごろにかけて雨の可能性があります。`
        );
      }
    }
  }

  if (
    maxProbability >=
    40
  ) {
    parts.push(
      `今後6時間の最大降水確率は約${Math.round(
        maxProbability
      )}%です。`
    );
  }

  if (
    maxRain >= 0.2
  ) {
    parts.push(
      `時間帯によっては1時間あたり約${maxRain.toFixed(
        1
      )}mm程度の降水が見込まれます。`
    );
  }

  if (
    thunder.length >
    0
  ) {
    parts.push(
      `${formatHour(
        thunder[0].time
      )}ごろを中心に雷雨の可能性があります。`
    );
  }

  /*
   * WMOコードの数字が一番大きいものを
   * 「強い状態」の目安として使う。
   */
  let strongest =
    points[0];

  for (
    const point
    of points
  ) {
    if (
      !strongest ||
      point.weatherCode >
        strongest.weatherCode
    ) {
      strongest =
        point;
    }
  }

  if (
    strongest
  ) {
    parts.push(
      `主な予報状態は「${weatherCodeToText(
        strongest.weatherCode
      )}」です。`
    );
  }

  return parts.join(
    " "
  );
}

async function getKotoWeatherForecastEvents():
  Promise<
    TokyoLifeEvent[]
  > {
  const hourly =
    [
      "precipitation_probability",
      "precipitation",
      "rain",
      "weather_code",
    ].join(
      ","
    );

  const url =
    "https://api.open-meteo.com/v1/forecast" +
    `?latitude=${MISAKI_LATITUDE}` +
    `&longitude=${MISAKI_LONGITUDE}` +
    `&hourly=${hourly}` +
    "&forecast_hours=6" +
    "&timezone=Asia%2FTokyo";

  const data =
    await fetchJson<
      OpenMeteoResponse
    >(
      url,
      300
    );

  if (
    !data?.hourly
  ) {
    return [];
  }

  const points =
    buildHourlyWeather(
      data.hourly
    ).slice(
      0,
      6
    );

  if (
    points.length ===
    0
  ) {
    return [];
  }

  /*
   * 晴れ・くもりだけなら
   * わざわざイベントとして
   * Geminiへ渡さない。
   *
   * 雨や雷など、
   * 会話に意味がある時だけ渡す。
   */
  if (
    !hasMeaningfulWeather(
      points
    )
  ) {
    return [];
  }

  const detail =
    createForecastDetail(
      points
    );

  if (
    !detail
  ) {
    return [];
  }

  return [
    {
      type:
        "weather_forecast",

      title:
        "江東区周辺の今後6時間の天気変化",

      detail,

      source:
        "Open-Meteo",
    },
  ];
}

