function getTrainSection(
  pageText: string,
  lineName: string
) {
  const start =
    pageText.indexOf(
      lineName
    );

  if (
    start < 0
  ) {
    return null;
  }

  let end =
    pageText.length;

  for (
    const otherLine
    of TOKYO_JR_LINES
  ) {
    if (
      otherLine ===
      lineName
    ) {
      continue;
    }

    const index =
      pageText.indexOf(
        otherLine,
        start +
          lineName.length
      );

    if (
      index > start &&
      index < end
    ) {
      end =
        index;
    }
  }

  end =
    Math.min(
      end,
      start + 500
    );

  return pageText.slice(
    start,
    end
  );
}

