import assert from "node:assert/strict";
import test from "node:test";
import {
  decodeLifeFactMemory,
  encodeLifeFactMemory,
  extractExplicitLifeFacts,
  selectRelevantLifeFacts,
  splitLifeFactMemory,
} from "../lib/relationship-life-context.ts";

test("明示した今日の予定は構造化記憶として次ターンへ持ち越せる", () => {
  const observedAt = "2026-09-25T10:00:00+09:00";
  const facts = extractExplicitLifeFacts("今日は休みだよ", observedAt);
  assert.equal(facts.length, 1);

  const encoded = encodeLifeFactMemory(facts[0]);
  const decoded = decodeLifeFactMemory(encoded);
  assert.ok(decoded);
  assert.equal(decoded.fact, "今日は休み");
  assert.equal(decoded.kind, "schedule");
  assert.equal(decoded.source, "user");

  const nextTurn = selectRelevantLifeFacts(
    [decoded],
    "2026-09-25T18:00:00+09:00"
  );
  assert.equal(nextTurn.length, 1);
});

test("持ち越した今日の予定は翌日には生活判断へ残らない", () => {
  const fact = extractExplicitLifeFacts(
    "今日は仕事だよ",
    "2026-09-25T10:00:00+09:00"
  )[0];
  const carried = decodeLifeFactMemory(encodeLifeFactMemory(fact));
  assert.ok(carried);

  const tomorrow = selectRelevantLifeFacts(
    [carried],
    "2026-09-26T09:00:00+09:00"
  );
  assert.equal(tomorrow.length, 0);
});

test("普通の長期記憶と期限付き生活記憶を分離できる", () => {
  const fact = extractExplicitLifeFacts(
    "明日は休み",
    "2026-09-25T10:00:00+09:00"
  )[0];
  const split = splitLifeFactMemory([
    "猫が好き",
    encodeLifeFactMemory(fact),
    "コーヒーはブラックが好き",
  ]);

  assert.deepEqual(split.ordinaryMemory, [
    "猫が好き",
    "コーヒーはブラックが好き",
  ]);
  assert.equal(split.facts.length, 1);
  assert.equal(split.facts[0].fact, "明日は休み");
});

test("壊れた構造化記憶は生活事実として採用しない", () => {
  assert.equal(decodeLifeFactMemory("[life:v1]{broken"), null);
  assert.equal(
    decodeLifeFactMemory('[life:v1]{"kind":"invented","fact":"今日は休み"}'),
    null
  );
});

import assert from "node:assert/strict";
import test from "node:test";

import { buildNaturalnessScenarioPreview } from "../lib/relationship-naturalness-scenario.ts";

test("quiet time after explicit rejection does not manufacture hidden affection", () => {
  const result = buildNaturalnessScenarioPreview({
    name: "拒絶→数日沈黙",
    context: {
      exists: true,
      elapsedSeconds: 72 * 3600,
      elapsedHours: 72,
      timeBand: "long_gap",
      intimacyLevel: "familiar",
      intimacyPoints: 55,
      emotionPrimary: "guarded",
      emotionIntensity: 52,
      actionState: "PULL",
      lastInteractionAt: "2026-09-22T00:00:00.000Z",
      stateUpdatedAt: "2026-09-22T00:00:00.000Z",
    },
    signals: {
      signals: [],
      relationshipFacts: { mutualAffectionExplicit: false, datingEstablishedExplicit: false },
    },
    recentConversation: "ユーザー: 恋愛としては見てない。\n美咲: ……そっか。わかった。",
    userMessage: "久しぶり",
  });

  assert.notEqual(result.emotion.primary, "affectionate");
  assert.match(result.systemPrompt, /存在しない交際事実|最初から恋人ではありません/);
});

test("sustained care can soften guardedness gradually without instant romance", () => {
  const result = buildNaturalnessScenarioPreview({
    name: "警戒→継続した気遣い",
    context: {
      exists: true,
      elapsedSeconds: 24 * 3600,
      elapsedHours: 24,
      timeBand: "next_day",
      intimacyLevel: "familiar",
      intimacyPoints: 70,
      emotionPrimary: "guarded",
      emotionIntensity: 44,
      actionState: "PULL",
      lastInteractionAt: "2026-09-24T00:00:00.000Z",
      stateUpdatedAt: "2026-09-24T00:00:00.000Z",
    },
    signals: {
      signals: [
        { name: "care", strength: 0.65, confidence: 0.9, evidence: "無理しなくていいよ" },
        { name: "warmth", strength: 0.55, confidence: 0.85, evidence: "ゆっくりで大丈夫" },
      ],
      relationshipFacts: { mutualAffectionExplicit: false, datingEstablishedExplicit: false },
    },
    patterns: { repeatedHarm: 1, reliableRepair: 1, sustainedCare: 3 },
    recentConversation: "ユーザー: 無理しなくていいよ。ゆっくりで大丈夫。",
