function time(value?: string | null) {
  if (!value) return null;
  const ms = new Date(value).getTime();
  return Number.isFinite(ms) ? ms : null;
}

export function selectRelevantLifeFacts(
  facts: LifeFact[],
  nowIso: string,
  max = 8
): RelevantLifeFact[] {
