  v_state public.misaki_relationship_state%rowtype;
  v_before jsonb;
  v_history jsonb;
  v_result jsonb;
  v_message text;
  v_now timestamptz:=clock_timestamp();
  v_silence bigint;
  v_revision timestamptz;
  v_point_delta integer;
