    setSendError: next => { error = next; }, setLoading() {}, setShowPremium() {}, applyApiUsage: () => { usage++; },
    fetch: async () => Response.json({ code: 'MAINTENANCE', maintenance: true, error: 'メンテナンス中です。' }, { status: 503 }),
