  requestId: string
) {
  const maxAttempts = 3;

  for (
    let attempt = 1;
    attempt <= maxAttempts;
    attempt += 1
  ) {
    const {
      data,
      error,
    } =
      await (
        supabase.rpc as any
      )(
        "consume_daily_message",
        {
          p_request_id:
            requestId,
        }
      );

    if (!error) {
      return {
        data,
        error: null,
      };
    }

    console.error(
      `USAGE RPC ERROR (${attempt}/${maxAttempts}):`,
      error
    );

    const text =
      typeof error.message ===
      "string"
        ? error.message.toLowerCase()
        : "";

    const retryable =
      text.includes("timeout") ||
      text.includes(
        "temporarily unavailable"
      ) ||
      text.includes(
        "fetch failed"
      );

    if (
      !retryable ||
      attempt === maxAttempts
    ) {
      return {
        data: null,
        error,
      };
    }

    await new Promise(
      (resolve) =>
        setTimeout(
          resolve,
          500 * attempt
        )
    );
  }

  return {
    data: null,
    error: new Error(
      "Usage retry failed"
    ),
  };
}

async function refundDailyMessage(
  supabase: SupabaseClient,
  requestId: string
) {
  const {
    data,
    error,
  } = await (
    supabase.rpc as any
  )(
    "refund_daily_message",
    {
      p_request_id:
        requestId,
    }
  );

  if (error) {
    console.error(
      "USAGE REFUND ERROR:",
      error
    );
    return null;
  }

  return getFirstRow<{
    refunded?: boolean;
    message_count?: number;
    remaining?: number;
    is_premium?: boolean;
  }>(data);
}

